-- Seed Snacky OS from docs/current-data CSV snapshots converted to deterministic SQL INSERTs.
-- Safe to rerun via `npx supabase db reset` or `npx supabase db push --include-seed`.
-- Seed helper functions live in migrations so Supabase Cloud has them before seed statements run.

insert into storage_locations (id, name, address) values ('00000000-0000-0000-0000-000000000201', 'MAIN', 'TO_CONFIRM') on conflict (id) do update set name = excluded.name, address = excluded.address;

insert into suppliers (id, name, contact_name, phone, payment_terms, notes) values
  ('00000000-0000-0000-0000-000000000301', 'TO_CONFIRM Supplier A', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'Seeded from CSV products'),
  ('00000000-0000-0000-0000-000000000302', 'TO_CONFIRM Supplier B', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'Seeded from CSV products')
on conflict do nothing;

with src_machines (machine_id, machine_name, location, logo, contact, notes, backstock_location_id, shelf_location_id) as (
values
  ('2509000371', 'اتش تي مول', 'سوق الجمعة', 'Places_Logos/htMall.webp', 'TO_CONFIRM', '', '2509000371', 'TO_CONFIRM'),
  ('2503000216', 'اتش تي لاند', 'سوق الجمعة', 'Places_Logos/htMall.webp', 'TO_CONFIRM', '', '2503000216', 'SHELF_2503000216'),
  ('2404120076', 'الدبلوماسي مول', 'عين زارة', 'Places_Logos/dpMall.webp', 'TO_CONFIRM', '', '2404120076', 'SHELF_2404120076'),
  ('2503000217', 'سي كوست', 'حي دمشق', 'Places_Logos/seaCoast.webp', 'TO_CONFIRM', '', '2503000217', 'SHELF_2503000217'),
  ('2411000046', 'مستشفى المواصفات', 'طريق المطار', 'Places_Logos/almHospital.webp', 'TO_CONFIRM', '', '2411000046', 'SHELF_2411000046'),
  ('2509000369', 'مستشفى الاستقلال', '', 'Machines_Images/4f241ed6.Logo.223116.jpg', 'TO_CONFIRM', '', 'TO_CONFIRM', 'SHELF_2509000369'),
  ('2509000370', 'جامعة التحدي', '', '', 'TO_CONFIRM', '', 'TO_CONFIRM', 'TO_CONFIRM'),
  ('2510001719', 'خليج ليبيا', '', '', 'TO_CONFIRM', '', 'TO_CONFIRM', 'TO_CONFIRM')
)
insert into locations (id, name, location_type, address, contact_name, status, notes)
select ('00000000-0000-0000-0000-' || lpad(row_number() over(order by coalesce(nullif(location,''),'TO_CONFIRM'))::text, 12, '0'))::uuid,
  coalesce(nullif(location,''), 'TO_CONFIRM'),'other'::location_type,coalesce(nullif(location,''), 'TO_CONFIRM'),'TO_CONFIRM','active','Seeded from docs/current-data/machines.csv'
from (select distinct location from src_machines) q
on conflict do nothing;

with src_machines (machine_id, machine_name, location, logo, contact, notes, backstock_location_id, shelf_location_id) as (
values
  ('2509000371', 'اتش تي مول', 'سوق الجمعة', 'Places_Logos/htMall.webp', 'TO_CONFIRM', '', '2509000371', 'TO_CONFIRM'),
  ('2503000216', 'اتش تي لاند', 'سوق الجمعة', 'Places_Logos/htMall.webp', 'TO_CONFIRM', '', '2503000216', 'SHELF_2503000216'),
  ('2404120076', 'الدبلوماسي مول', 'عين زارة', 'Places_Logos/dpMall.webp', 'TO_CONFIRM', '', '2404120076', 'SHELF_2404120076'),
  ('2503000217', 'سي كوست', 'حي دمشق', 'Places_Logos/seaCoast.webp', 'TO_CONFIRM', '', '2503000217', 'SHELF_2503000217'),
  ('2411000046', 'مستشفى المواصفات', 'طريق المطار', 'Places_Logos/almHospital.webp', 'TO_CONFIRM', '', '2411000046', 'SHELF_2411000046'),
  ('2509000369', 'مستشفى الاستقلال', '', 'Machines_Images/4f241ed6.Logo.223116.jpg', 'TO_CONFIRM', '', 'TO_CONFIRM', 'SHELF_2509000369'),
  ('2509000370', 'جامعة التحدي', '', '', 'TO_CONFIRM', '', 'TO_CONFIRM', 'TO_CONFIRM'),
  ('2510001719', 'خليج ليبيا', '', '', 'TO_CONFIRM', '', 'TO_CONFIRM', 'TO_CONFIRM')
)
insert into machines (machine_code, vms_machine_id, name, machine_type, location_id, status, notes)
select 'SNK-' || machine_id,machine_id,machine_name,'lift',l.id,'active',coalesce(nullif(m.notes,''), 'Seeded from machines.csv')
from src_machines m left join locations l on l.name = coalesce(nullif(m.location,''), 'TO_CONFIRM')
on conflict (machine_code) do update set vms_machine_id = excluded.vms_machine_id,name = excluded.name,location_id = excluded.location_id,notes = excluded.notes;

