), purchase_source_rows as (
  select distinct on (source_row) *
  from purchase_source_rows_raw
  order by source_row,
    (case when public.snacky_seed_clean_text(purchase_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(line_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(item_id) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(qty_pieces) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(unit_cost) is not null then 1 else 0 end) desc
)
insert into suppliers (id, name, notes)
select md5('seed:supplier:' || supplier_name)::uuid, supplier_name, 'Seeded from docs/current-data/purchases.csv'
from (
  select distinct public.snacky_seed_clean_text(supplier) as supplier_name
  from purchase_source_rows
) source_suppliers
where supplier_name is not null
  and not exists (
    select 1
    from suppliers existing_supplier
    where existing_supplier.name = source_suppliers.supplier_name
  )
on conflict (id) do nothing;

