), purchase_source_rows as (
  select distinct on (source_row) *
  from purchase_source_rows_raw
  order by source_row,
    (case when public.snacky_seed_clean_text(purchase_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(line_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(item_id) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(qty_pieces) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(unit_cost) is not null then 1 else 0 end) desc
), normalized_purchase_lines as (
  select
    spr.source_row,
    public.snacky_seed_clean_text(spr.purchase_id) as purchase_id,
    coalesce(public.snacky_seed_date(spr.datetime), current_date) as order_date,
    lower(public.snacky_seed_clean_text(spr.operator_email)) as operator_email,
    public.snacky_seed_clean_text(spr.supplier) as supplier_name,
    coalesce(public.snacky_seed_numeric(spr.receipt_total), 0) as receipt_total,
    coalesce(public.snacky_seed_numeric(spr.calculated_total), 0) as source_calculated_total,
    public.snacky_seed_clean_text(spr.receipt_photo) as receipt_photo,
    public.snacky_seed_clean_text(spr.notes) as source_notes,
    public.snacky_seed_clean_text(spr.line_id) as source_line_id,
    p.id as product_id,
    greatest(0, round(coalesce(public.snacky_seed_numeric(spr.qty_pieces), 0))::integer) as total_units,
    round(coalesce(public.snacky_seed_numeric(spr.unit_cost), 0), 4) as unit_cost_lyd
  from purchase_source_rows spr
  join products p on p.sku = public.snacky_seed_clean_text(spr.item_id)
  where public.snacky_seed_clean_text(spr.purchase_id) is not null
    and greatest(0, round(coalesce(public.snacky_seed_numeric(spr.qty_pieces), 0))::integer) > 0
), numbered_purchase_lines as (
  select
    npl.*,
    row_number() over (partition by npl.purchase_id order by npl.source_row) - 1 as line_position
  from normalized_purchase_lines npl
), purchase_groups as (
  select
    purchase_id,
    min(order_date) as order_date,
    max(operator_email) as operator_email,
    max(supplier_name) as supplier_name,
    max(receipt_total) as receipt_total,
    max(source_calculated_total) as source_calculated_total,
    round(sum(total_units * unit_cost_lyd), 2) as computed_total,
    max(receipt_photo) as receipt_photo,
    max(source_notes) as source_notes
  from numbered_purchase_lines
  group by purchase_id
), purchase_payloads as (
  select
    md5('seed:purchase_order:' || pg.purchase_id)::uuid as id,
    supplier.id as supplier_id,
    pg.purchase_id,
    pg.order_date,
    pg.operator_email,
    pg.receipt_photo,
    pg.source_notes,
    case when pg.receipt_total > 0 then round(pg.receipt_total, 2) else null end as manual_total_lyd,
    case when pg.source_calculated_total > 0 then round(pg.source_calculated_total, 2) else pg.computed_total end as calculated_total_lyd
  from purchase_groups pg
  left join lateral (
    select s.id
    from suppliers s
    where s.name = pg.supplier_name
    order by s.created_at, s.id
    limit 1
  ) supplier on true
)
insert into purchase_orders (
  id,
  supplier_id,
  status,
  order_date,
  received_date,
  receipt_number,
  payment_method,
  payment_status,
  receipt_url,
  total_amount,
  manual_total_lyd,
  calculated_total_lyd,
  total_adjustment_lyd,
  total_source,
  created_by,
  received_by,
  received_at,
  notes
)
select
  pp.id,
  pp.supplier_id,
  'received',
  pp.order_date,
  pp.order_date,
  pp.purchase_id,
  'cash',
  'paid',
  null,
  coalesce(pp.manual_total_lyd, pp.calculated_total_lyd, 0),
  pp.manual_total_lyd,
  coalesce(pp.calculated_total_lyd, 0),
  case when pp.manual_total_lyd is null then null else round(pp.manual_total_lyd - coalesce(pp.calculated_total_lyd, 0), 2) end,
  case when pp.manual_total_lyd is null then 'calculated' else 'manual' end,
  null,
  null,
  pp.order_date::timestamptz,
  concat_ws(E'\n',
    'seed:purchase:source_id=' || pp.purchase_id || ':source=docs/current-data/purchases.csv',
    case when pp.operator_email is not null then 'operator_email=' || pp.operator_email end,
    case when pp.receipt_photo is not null then 'source_receipt_photo=' || pp.receipt_photo end,
    case when pp.source_notes is not null then 'source_notes=' || pp.source_notes end,
    'Historical purchase import; current inventory is represented separately by inventory movements.'
  )
from purchase_payloads pp
where not exists (
  select 1
  from purchase_orders existing_order
  where existing_order.id = pp.id
    or existing_order.receipt_number = pp.purchase_id
)
on conflict (id) do nothing;

