  (522, 'e00ef670', '2026-05-05', 'anasgherfal@gmail.com', 'TO_CONFIRM', '603.0', '0.0', 'Purchases_Images/e00ef670.ReceiptPhoto.234711.jpg', '', 'f96b7bda', 'bb6c2490', 'TO_CONFIRM', '2.78', '10.0', '180.0', '18.0'),
  (523, 'e00ef670', '2026-05-05', 'anasgherfal@gmail.com', 'TO_CONFIRM', '603.0', '0.0', 'Purchases_Images/e00ef670.ReceiptPhoto.234711.jpg', '', '388f37e0', 'd5b5f9d1', 'TO_CONFIRM', '2.6', '1.0', '15.0', '15.0')
), purchase_source_rows as (
  select distinct on (source_row) *
  from purchase_source_rows_raw
  order by source_row,
    (case when public.snacky_seed_clean_text(purchase_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(line_id) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(item_id) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(qty_pieces) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(unit_cost) is not null then 1 else 0 end) desc
), normalized_purchase_lines as (
  select
    spr.source_row,
    public.snacky_seed_clean_text(spr.purchase_id) as purchase_id,
    public.snacky_seed_clean_text(spr.line_id) as source_line_id,
    p.id as product_id,
    greatest(0, round(coalesce(public.snacky_seed_numeric(spr.qty_pieces), 0))::integer) as total_units,
    round(coalesce(public.snacky_seed_numeric(spr.unit_cost), 0), 4) as unit_cost_lyd
  from purchase_source_rows spr
  join products p on p.sku = public.snacky_seed_clean_text(spr.item_id)
  where public.snacky_seed_clean_text(spr.purchase_id) is not null
    and greatest(0, round(coalesce(public.snacky_seed_numeric(spr.qty_pieces), 0))::integer) > 0
), numbered_purchase_lines as (
  select
    npl.*,
    row_number() over (partition by npl.purchase_id order by npl.source_row) - 1 as line_position
  from normalized_purchase_lines npl
), purchase_line_payloads as (
  select
    md5('seed:purchase_line:' || coalesce(npl.source_line_id, npl.purchase_id || ':' || npl.source_row::text))::uuid as id,
    purchase_order.id as purchase_order_id,
    npl.line_position,
    npl.product_id,
    npl.total_units,
    npl.unit_cost_lyd,
    round(npl.total_units * npl.unit_cost_lyd, 2) as line_total_lyd
  from numbered_purchase_lines npl
  join lateral (
    select po.id
    from purchase_orders po
    where po.id = md5('seed:purchase_order:' || npl.purchase_id)::uuid
       or po.receipt_number = npl.purchase_id
    order by (po.id = md5('seed:purchase_order:' || npl.purchase_id)::uuid) desc, po.created_at, po.id
    limit 1
  ) purchase_order on true
)
insert into purchase_order_lines (
  id,
  purchase_order_id,
  line_position,
  product_id,
  boxes_qty,
  units_per_box,
  loose_units_qty,
  total_units,
  ordered_qty,
  received_qty,
  unit_cost,
  unit_cost_lyd,
  line_total,
  line_total_lyd
)
select
  plp.id,
  plp.purchase_order_id,
  plp.line_position,
  plp.product_id,
  0,
  1,
  plp.total_units,
  plp.total_units,
  plp.total_units,
  plp.total_units,
  round(plp.unit_cost_lyd, 2),
  plp.unit_cost_lyd,
  plp.line_total_lyd,
  plp.line_total_lyd
from purchase_line_payloads plp
where not exists (
  select 1
  from purchase_order_lines existing_line
  where existing_line.id = plp.id
     or (existing_line.purchase_order_id = plp.purchase_order_id and existing_line.line_position = plp.line_position)
)
on conflict (id) do nothing;

