  (528, '2026-05-15', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', '0.0', 'Review', 'TO_CONFIRM', 'Review')
), financial_source_rows as (
  select distinct on (source_row) *
  from financial_source_rows_raw
  order by source_row,
    (case when public.snacky_seed_date(transaction_date) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(signed_amount) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(transaction_amount) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(money_flow) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(final_bucket) is not null then 1 else 0 end) desc
), normalized_financial_transactions as (
  select
    sft.source_row,
    public.snacky_seed_date(sft.transaction_date) as transaction_date,
    coalesce(public.snacky_seed_numeric(sft.signed_amount), public.snacky_seed_numeric(sft.transaction_amount)) as raw_signed_amount,
    public.snacky_seed_clean_text(sft.money_flow) as money_flow,
    public.snacky_seed_clean_text(sft.transaction_type) as transaction_type,
    public.snacky_seed_clean_text(sft.location) as location,
    public.snacky_seed_clean_text(sft.transaction_description) as description,
    public.snacky_seed_clean_text(sft.auto_bucket) as bucket,
    public.snacky_seed_clean_text(sft.bucket_override) as bucket_override,
    public.snacky_seed_clean_text(sft.final_bucket) as final_bucket,
    coalesce(
      nullif(public.snacky_seed_clean_text(sft.final_bucket), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.bucket_override), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.auto_bucket), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.transaction_type), 'Review')
    ) as category,
    coalesce(public.snacky_seed_clean_text(sft.final_bucket), public.snacky_seed_clean_text(sft.bucket_override), public.snacky_seed_clean_text(sft.auto_bucket), public.snacky_seed_clean_text(sft.transaction_type), 'Review') as category_for_transaction,
    public.snacky_seed_clean_text(sft.transaction_amount) as raw_transaction_amount
  from financial_source_rows sft
), classified_financial_transactions as (
  select
    nft.*,
    case
      when lower(nft.money_flow) in ('money in', 'in', 'income', 'revenue', 'cash in') then 'money_in'
      when lower(nft.money_flow) in ('money out', 'out', 'expense', 'expenses', 'cash out') then 'money_out'
      else null
    end as direction
  from normalized_financial_transactions nft
), financial_payloads as (
  select
    md5('seed:financial_transaction:financial_transactions.csv:' || cft.source_row::text)::uuid as id,
    cft.*,
    case
      when cft.direction = 'money_out' then -abs(round(cft.raw_signed_amount, 2))
      when cft.direction = 'money_in' then abs(round(cft.raw_signed_amount, 2))
      else null
    end as signed_amount,
    concat_ws('; ',
      case when cft.transaction_date is null then 'date missing or invalid' end,
      case when cft.raw_signed_amount is null then 'amount missing or invalid' end,
      case when cft.direction is null then 'direction unclear' end,
      case when cft.category is null then 'category unclear' end
    ) as review_reason
  from classified_financial_transactions cft
), transaction_payloads as (
  select *
  from financial_payloads
  where transaction_date is not null
    and direction is not null
    and signed_amount is not null
    and signed_amount <> 0
)
insert into financial_transactions (
  id,
  transaction_date,
  direction,
  transaction_kind,
  transaction_type,
  location,
  description,
  amount,
  signed_amount,
  bucket,
  bucket_override,
  final_bucket,
  review_status,
  needs_review,
  source_sheet,
  source_row,
  source_file,
  original_description,
  import_status,
  transaction_status,
  metadata
)
select
  tp.id,
  tp.transaction_date,
  tp.direction,
  'spreadsheet_import',
  tp.transaction_type,
  tp.location,
  tp.description,
  abs(tp.signed_amount),
  tp.signed_amount,
  tp.bucket,
  tp.bucket_override,
  tp.category_for_transaction,
  case when tp.review_reason is null or tp.review_reason = '' then 'confirmed' else 'needs_review' end,
  not (tp.review_reason is null or tp.review_reason = ''),
  'financial_transactions.csv',
  tp.source_row,
  'docs/current-data/financial_transactions.csv',
  tp.description,
  case when tp.review_reason is null or tp.review_reason = '' then 'imported' else 'needs_review' end,
  'active',
  jsonb_build_object(
    'seed_source', 'docs/current-data/financial_transactions.csv',
    'money_flow', tp.money_flow,
    'raw_transaction', tp.raw_transaction_amount,
    'review_reason', nullif(tp.review_reason, '')
  )
from transaction_payloads tp
where not exists (
  select 1
  from financial_transactions existing_transaction
  where existing_transaction.source_sheet = 'financial_transactions.csv'
    and existing_transaction.source_row = tp.source_row
)
on conflict do nothing;

