  (518, '2026-04-30', '2564', 'Money In', 'Revenue', 'HTLand', 'TO_CONFIRM', '2564.0', 'Inflow', 'TO_CONFIRM', 'Inflow'),
  (519, '2026-04-30', '1276', 'Money In', 'Revenue', 'AlmouasafatHospital', 'TO_CONFIRM', '1276.0', 'Inflow', 'TO_CONFIRM', 'Inflow'),
  (520, '2026-04-30', '2335', 'Money In', 'Revenue', 'Istiklal', 'TO_CONFIRM', '2335.0', 'Inflow', 'TO_CONFIRM', 'Inflow'),
  (521, '2026-04-30', '874', 'Money In', 'Revenue', 'HTMall', 'TO_CONFIRM', '874.0', 'Inflow', 'TO_CONFIRM', 'Inflow'),
  (522, '2026-04-30', '544', 'Money In', 'Revenue', 'KhalijUniversity', 'TO_CONFIRM', '544.0', 'Inflow', 'TO_CONFIRM', 'Inflow'),
  (523, '2026-05-01', '1488', 'Money Out', 'Product Restocking', 'TO_CONFIRM', 'TO_CONFIRM', '-1488.0', 'Inventory', 'TO_CONFIRM', 'Inventory'),
  (524, '2026-05-02', '1201', 'Money Out', 'Product Restocking', 'TO_CONFIRM', 'TO_CONFIRM', '-1201.0', 'Inventory', 'TO_CONFIRM', 'Inventory'),
  (525, '2026-05-03', '827', 'Money Out', 'Product Restocking', 'TO_CONFIRM', 'TO_CONFIRM', '-827.0', 'Inventory', 'TO_CONFIRM', 'Inventory'),
  (526, '2026-05-05', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', '0.0', 'Review', 'TO_CONFIRM', 'Review'),
  (527, '2026-05-14', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', '0.0', 'Review', 'TO_CONFIRM', 'Review'),
  (528, '2026-05-15', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', 'TO_CONFIRM', '0.0', 'Review', 'TO_CONFIRM', 'Review')
), financial_source_rows as (
  select distinct on (source_row) *
  from financial_source_rows_raw
  order by source_row,
    (case when public.snacky_seed_date(transaction_date) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(signed_amount) is not null then 1 else 0 end +
     case when public.snacky_seed_numeric(transaction_amount) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(money_flow) is not null then 1 else 0 end +
     case when public.snacky_seed_clean_text(final_bucket) is not null then 1 else 0 end) desc
), normalized_financial_transactions as (
  select
    sft.source_row,
    public.snacky_seed_date(sft.transaction_date) as transaction_date,
    coalesce(public.snacky_seed_numeric(sft.signed_amount), public.snacky_seed_numeric(sft.transaction_amount)) as raw_signed_amount,
    public.snacky_seed_clean_text(sft.money_flow) as money_flow,
    public.snacky_seed_clean_text(sft.transaction_type) as transaction_type,
    public.snacky_seed_clean_text(sft.location) as location,
    public.snacky_seed_clean_text(sft.transaction_description) as description,
    public.snacky_seed_clean_text(sft.auto_bucket) as bucket,
    public.snacky_seed_clean_text(sft.bucket_override) as bucket_override,
    public.snacky_seed_clean_text(sft.final_bucket) as final_bucket,
    coalesce(
      nullif(public.snacky_seed_clean_text(sft.final_bucket), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.bucket_override), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.auto_bucket), 'Review'),
      nullif(public.snacky_seed_clean_text(sft.transaction_type), 'Review')
    ) as category,
    coalesce(public.snacky_seed_clean_text(sft.final_bucket), public.snacky_seed_clean_text(sft.bucket_override), public.snacky_seed_clean_text(sft.auto_bucket), public.snacky_seed_clean_text(sft.transaction_type), 'Review') as raw_category,
    public.snacky_seed_clean_text(sft.transaction_amount) as raw_transaction_amount,
    sft.transaction_date as raw_date,
    sft.signed_amount as raw_signed_amount_text,
    sft.transaction_amount as raw_transaction_amount_text,
    sft.money_flow as raw_money_flow
  from financial_source_rows sft
), classified_financial_transactions as (
  select
    nft.*,
    case
      when lower(nft.money_flow) in ('money in', 'in', 'income', 'revenue', 'cash in') then 'money_in'
      when lower(nft.money_flow) in ('money out', 'out', 'expense', 'expenses', 'cash out') then 'money_out'
      else null
    end as direction
  from normalized_financial_transactions nft
), stage_payloads as (
  select
    cft.*,
    case
      when cft.direction = 'money_out' then -abs(round(cft.raw_signed_amount, 2))
      when cft.direction = 'money_in' then abs(round(cft.raw_signed_amount, 2))
      else null
    end as signed_amount,
    concat_ws('; ',
      case when cft.transaction_date is null then 'date missing or invalid' end,
      case when cft.raw_signed_amount is null then 'amount missing or invalid' end,
      case when cft.direction is null then 'direction unclear' end,
      case when cft.category is null then 'category unclear' end
    ) as review_reason
  from classified_financial_transactions cft
), linked_stage_payloads as (
  select
    sp.*,
    ft.id as financial_transaction_id
  from stage_payloads sp
  left join financial_transactions ft
    on ft.source_sheet = 'financial_transactions.csv'
   and ft.source_row = sp.source_row
)
insert into finance_import_rows (
  source_file,
  source_sheet,
  source_row,
  import_status,
  transaction_date,
  raw_date,
  amount,
  signed_amount,
  raw_amount,
  direction,
  raw_direction,
  category,
  raw_category,
  original_description,
  review_reason,
  financial_transaction_id,
  raw_record,
  updated_at
)
select
  'docs/current-data/financial_transactions.csv',
  'financial_transactions.csv',
  lsp.source_row,
  case when lsp.review_reason is null or lsp.review_reason = '' then 'imported' else 'needs_review' end,
  lsp.transaction_date,
  lsp.raw_date,
  case when lsp.signed_amount is null then null else abs(lsp.signed_amount) end,
  lsp.signed_amount,
  coalesce(lsp.raw_signed_amount_text, lsp.raw_transaction_amount_text),
  lsp.direction,
  lsp.raw_money_flow,
  lsp.category,
  lsp.raw_category,
  lsp.description,
  nullif(lsp.review_reason, ''),
  lsp.financial_transaction_id,
  jsonb_build_object(
    'date', lsp.raw_date,
    'transaction', lsp.raw_transaction_amount_text,
    'money_flow', lsp.raw_money_flow,
    'transaction_type', lsp.transaction_type,
    'location', lsp.location,
    'transaction_description', lsp.description,
    'signed_amount', lsp.raw_signed_amount_text,
    'auto_bucket', lsp.bucket,
    'bucket_override', lsp.bucket_override,
    'final_bucket', lsp.final_bucket
  ),
  now()
from linked_stage_payloads lsp
on conflict (source_file, source_sheet, source_row) do update set
  import_status = excluded.import_status,
  transaction_date = excluded.transaction_date,
  raw_date = excluded.raw_date,
  amount = excluded.amount,
  signed_amount = excluded.signed_amount,
  raw_amount = excluded.raw_amount,
  direction = excluded.direction,
  raw_direction = excluded.raw_direction,
  category = excluded.category,
  raw_category = excluded.raw_category,
  original_description = excluded.original_description,
  review_reason = excluded.review_reason,
  financial_transaction_id = excluded.financial_transaction_id,
  raw_record = excluded.raw_record,
  updated_at = now();

