  sku,
  name,
  category,
  cost_price,
  selling_price,
  current_cost_price_lyd,
  current_selling_price_lyd,
  cost_price_source,
  selling_price_source,
  import_source,
  active
)
select
  sst.sku,
  coalesce(nullif(sst.product_name, ''), 'Imported item ' || sst.sku),
  'unknown',
  0,
  0,
  0,
  0,
  'initial_import',
  'initial_import',
  'storage_target_seed',
  true
from storage_target_rows sst
where not exists (
  select 1
  from products p
  where p.sku = sst.sku
)
on conflict (sku) do nothing;

