), storage_target_rows as (
  select distinct on (sku) sku, product_name, target_quantity
  from storage_target_rows_raw
  where public.snacky_seed_clean_text(sku) is not null
  order by sku,
    (case when public.snacky_seed_clean_text(product_name) is not null then 1 else 0 end) desc,
    abs(target_quantity) desc
), main_storage as (
  select id
  from storage_locations
  where name = 'MAIN'
  order by created_at, id
  limit 1
), targets as (
  select
    p.id as product_id,
    p.sku,
    sst.target_quantity
  from storage_target_rows sst
  join products p on p.sku = sst.sku
), current_storage as (
  select
    t.product_id,
    coalesce(sum(civ.quantity_on_hand), 0)::integer as current_quantity
  from targets t
  left join current_inventory_by_location civ
    on civ.product_id = t.product_id
   and civ.location_type = 'storage'
  group by t.product_id
), deltas as (
  select
    t.product_id,
    t.sku,
    t.target_quantity,
    t.target_quantity - cs.current_quantity as delta_quantity,
    ms.id as main_storage_id
  from targets t
  join current_storage cs on cs.product_id = t.product_id
  cross join main_storage ms
)
insert into inventory_movements (
  product_id,
  quantity,
  from_entity_type,
  from_entity_id,
  to_entity_type,
  to_entity_id,
  reason,
  notes,
  created_at
)
select
  d.product_id,
  abs(d.delta_quantity),
  case when d.delta_quantity > 0 then 'adjustment'::inventory_entity_type else 'storage'::inventory_entity_type end,
  case when d.delta_quantity > 0 then null else d.main_storage_id end,
  case when d.delta_quantity > 0 then 'storage'::inventory_entity_type else 'adjustment'::inventory_entity_type end,
  case when d.delta_quantity > 0 then d.main_storage_id else null end,
  'stock_count_adjustment',
  'seed:storage_target_balance:sku=' || d.sku || ':target=' || d.target_quantity || ':source=local_current_inventory_by_location',
  now()
from deltas d
where d.delta_quantity <> 0;
